python3 << 'PYEOF'
import json

with open('/tmp/trivy_results.json') as f:
    trivy = json.load(f)

results = trivy.get('Results', [])
for result in results:
    vulns = result.get('Vulnerabilities', [])
    if not vulns:
        continue
    for v in vulns:
        severity = v.get('Severity', '').upper()
        if severity not in ('HIGH', 'CRITICAL'):
            continue
        pkg = v.get('PkgName', '')
        version = v.get('InstalledVersion', '')
        cve = v.get('VulnerabilityID', '')
        title = v.get('Title', '')
        fixed = v.get('FixedVersion', '')
        cvss_score = ''
        # Try to get CVSS score from various sources
        cvss_data = v.get('CVSS', {})
        for source in ['ghsa', 'nvd', 'redhat']:
            for src_key, src_val in cvss_data.items():
                if source in src_key.lower():
                    if 'V3Score' in src_val:
                        cvss_score = src_val['V3Score']
                        break
            if cvss_score:
                break
        if not cvss_score:
            for src_key, src_val in cvss_data.items():
                if 'V3Score' in src_val:
                    cvss_score = src_val['V3Score']
                    break

        refs = v.get('PrimaryURL', '')

        print(f"CVE: {cve} | PKG: {pkg} | VER: {version} | SEV: {severity} | CVSS: {cvss_score} | FIXED: {fixed} | TITLE: {title} | URL: {refs}")

PYEOF

