import json, sys
data = json.load(sys.stdin)
pkgs = set()
for r in data.get('Results', []):
    for v in r.get('Vulnerabilities', []):
        pkgs.add(v.get('PkgName',''))
    for p in r.get('Packages', []):
        pkgs.add(p.get('Name',''))
